WITH base AS (SELECT *, CASE WHEN channel IN ('mobile', 'web') THEN 'Priority' ELSE 'Other' END AS channel_group, MONTH(ends_on) AS ends_on_month FROM promotions WHERE starts_on >= DATE '2023-05-17' AND channel IS DISTINCT FROM 'mobile'), latest AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY promo_code ORDER BY starts_on DESC, id) AS rank_in_group FROM base) t WHERE rank_in_group = 1), enriched AS (SELECT id, promo_code, discount_pct, channel_group, ends_on_month, rank_in_group, PERCENT_RANK() OVER (PARTITION BY channel ORDER BY ends_on_month NULLS LAST) AS ends_on_month_percent_rank, ROW_NUMBER() OVER (PARTITION BY promo_code ORDER BY discount_pct, id) AS seq_no FROM latest), cleaned AS (SELECT id, promo_code, discount_pct, rank_in_group, seq_no, UPPER(promo_code) AS promo_code_upper, ROUND(discount_pct, 2) AS discount_pct_rounded FROM enriched WHERE rank_in_group >= 1), matched_keys AS (SELECT promo_code FROM cleaned EXCEPT ALL SELECT promo_code FROM promotions WHERE discount_pct >= 0.17), verified AS (SELECT s.* FROM cleaned s JOIN matched_keys k ON s.promo_code = k.promo_code) SELECT seq_no, MAX(discount_pct) FILTER (WHERE promo_code = 'BUNDLE') AS bundle_max_discount_pct, MIN(seq_no) AS min_seq_no, COUNT_IF(promo_code = 'SPRING10') AS spring10_events, ROUND(AVG(discount_pct_rounded), 2) AS avg_discount_pct_rounded FROM verified GROUP BY seq_no HAVING ROUND(AVG(discount_pct_rounded), 2) > 0 ORDER BY avg_discount_pct_rounded NULLS LAST
